<script setup lang="ts">
import { ref,computed,onMounted,onUnmounted,nextTick } from 'vue';
import Icon from './Icon.vue';import Modal from './ui/Modal.vue';
import Attachment from './Attachment.vue';import AttachmentUpload from './AttachmentUpload.vue';
import { api,bootstrap,initials,relative,login } from '../lib/api';
import type { Bootstrap } from '../lib/model';
const state=ref<Bootstrap>();const tab=ref('tickets');const activeId=ref('');const error=ref('');const busy=ref(false);const draft=ref('');const modal=ref(false);const query=ref('');const toast=ref('');const form=ref({subject:'',text:'',priority:'normal',channel:'portal'});const thread=ref<HTMLElement>();let polling:ReturnType<typeof setInterval>;
const w=computed(()=>state.value?.workspace);const selected=computed(()=>w.value?.conversations.find(c=>c.id===activeId.value));const articles=computed(()=>(w.value?.articles||[]).filter(a=>`${a.title} ${a.body}`.toLowerCase().includes(query.value.toLowerCase())));
async function load(){try{const workspace=localStorage.getItem('sahdev-workspace')||undefined;state.value=await bootstrap(workspace,true);error.value='';if(state.value.session.role!=='client')error.value='This workspace does not have a customer identity for your account. Use a client membership or open the sample workspace.';}catch(e:any){error.value=e.message;}}
async function mutate(path:string,body:unknown){if(!state.value)return;busy.value=true;try{const r=await api(path,{method:'POST',body,workspace:w.value!.id,version:state.value.version,portal:true});await load();return r;}catch(e:any){if(e.status===409)await load();throw e;}finally{busy.value=false;}}
async function create(){try{const r=await mutate('/conversations',form.value);activeId.value=r.result.id;modal.value=false;form.value={subject:'',text:'',priority:'normal',channel:'portal'};toast.value='Your request is with the team.';}catch(e:any){error.value=e.message;}}
async function send(){if(!selected.value||!draft.value.trim())return;try{await mutate('/conversations/'+selected.value.id+'/messages',{text:draft.value,kind:'reply'});draft.value='';toast.value='Message sent.';await nextTick();thread.value?.scrollTo({top:thread.value.scrollHeight,behavior:'smooth'});}catch(e:any){error.value=e.message;}}
function theme(){const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;localStorage.setItem('sahdev-theme',value);}
onMounted(async()=>{await load();polling=setInterval(()=>{if(!busy.value&&!modal.value)load();},10000);});onUnmounted(()=>clearInterval(polling));
</script>
<template><div class="portal-page"><header class="portal-nav"><a class="brand" href="/"><img src="/favicon.svg" alt="" width="31"/>sahdev</a><div class="nav-links"><a href="/app/">Team workspace <span>↗</span></a><button class="icon-button" aria-label="Toggle color theme" @click="theme"><Icon name="sun"/></button><span v-if="state" class="avatar peach">{{initials(state.session.name)}}</span></div></header><div v-if="w?.sample" class="portal-sample">Sample customer preview · You’re viewing Olivia’s conversations. Internal notes are hidden by the server.</div><section class="portal-hero"><div class="eyebrow"><span class="live-dot"></span> YOUR SPACE FOR SUPPORT</div><h1>Good to see you{{state?.session.role==='client'?', '+state.session.name.split(' ')[0]:''}}.</h1><p>{{w?.settings.welcome||'A question, an idea, a little help. We’re here for it.'}}</p></section><main class="portal-container"><div class="portal-tabs"><button :class="{active:tab==='tickets'}" @click="tab='tickets'"><Icon name="chat" :size="16"/>Your conversations</button><button :class="{active:tab==='knowledge'}" @click="tab='knowledge';activeId=''"><Icon name="book" :size="16"/>Help center</button></div><div v-if="error" class="form-error mb-5" role="alert">{{error}} <button v-if="!state" class="button secondary ml-3" @click="login().catch(e=>error=e.message)">Sign in</button></div><template v-if="state?.session.role==='client'"><template v-if="tab==='tickets'&&!selected"><div class="portal-toolbar"><h2>Your conversations <span class="pill subtle">{{w!.conversations.length}}</span></h2><button class="button primary" @click="modal=true"><Icon name="plus" :size="16"/>New request</button></div><button v-for="c in [...w!.conversations].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))" :key="c.id" class="portal-ticket" @click="activeId=c.id"><span class="portal-ticket-icon"><Icon :name="c.channel==='chat'?'chat':'file'"/></span><div><h3>{{c.subject}}</h3><p>#{{c.id.slice(0,8)}} · {{c.messages.length}} messages · Updated {{relative(c.updatedAt)}} ago</p></div><span :class="['status',c.status]">{{c.status}}</span><Icon name="right" :size="17"/></button><div v-if="!w!.conversations.length" class="empty-state panel portal-empty"><Icon name="chat" :size="38"/><h2>Let’s start a conversation.</h2><p>Send a request and your support team will help you from here.</p><button class="button primary" @click="modal=true">Create your first request</button></div></template><template v-else-if="tab==='tickets'&&selected"><button class="text-action mb-5" @click="activeId=''">← All conversations</button><section class="portal-thread"><header class="thread-heading"><div><h2>{{selected.subject}}</h2><p>#{{selected.id.slice(0,8)}} · {{selected.priority}} priority</p></div><span :class="['status',selected.status]">{{selected.status}}</span></header><div class="thread-timeline" ref="thread"><article v-for="m in selected.messages" :key="m.id" :class="['message',m.kind==='customer'?'reply':'customer']"><span :class="['avatar small',m.kind==='customer'?'peach':'owner']">{{initials(m.author)}}</span><div class="message-body"><div class="message-byline"><strong>{{m.author}}</strong><time>{{new Date(m.at).toLocaleString('en-IN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}}</time></div><div class="message-text">{{m.text}}<Attachment v-if="m.attachment" :file="m.attachment" :conversation="selected.id" :workspace="w!.id" portal @error="error=$event"/></div></div></article></div><div class="composer"><textarea v-model="draft" placeholder="Add a little more context…" aria-label="Write your message" maxlength="8000" @keydown.ctrl.enter.prevent="send"/><div class="composer-bottom"><AttachmentUpload :conversation="selected.id" :workspace="w!.id" :version="state.version" portal @uploaded="load();toast='File attached'" @error="error=$event"/><span><Icon name="shield" :size="14"/>{{selected.status==='resolved'?'Replying reopens this conversation':'Only you and your support team'}}</span><button class="button primary" :disabled="busy||!draft.trim()" @click="send">{{busy?'Sending…':'Send message'}}<Icon name="send" :size="15"/></button></div></div></section></template><template v-else><div class="portal-toolbar"><h2>A little help, right here.</h2><div class="list-search"><Icon name="search" :size="16"/><input v-model="query" placeholder="Search help articles…" aria-label="Search help articles"/></div></div><details v-for="article in articles" :key="article.id" class="help-article"><summary><Icon name="book" :size="18"/><span>{{article.title}}</span><Icon name="plus" :size="16"/></summary><p>{{article.body}}</p></details><div v-if="!articles.length" class="empty-state panel"><Icon name="book" :size="32"/><h2>No matching articles yet.</h2><p>Start a conversation and the team will help.</p></div></template></template><div v-else-if="!error" class="empty-state">Opening your support space…</div></main><footer class="portal-footer"><span><Icon name="shield" :size="13" class="inline mr-1"/> A private conversation. A human on your side.</span><span>Powered by Sahdev</span></footer><div v-if="toast" class="toast" role="status"><Icon name="check" :size="16"/>{{toast}}<button @click="toast=''" aria-label="Dismiss"><Icon name="x" :size="15"/></button></div><Modal :open="modal" @update:open="modal=$event" title="How can we help?" description="Tell us what’s happening. Your team will pick it up from here."><form class="modal-form" @submit.prevent="create"><label>Subject<input v-model="form.subject" required minlength="3" maxlength="150" placeholder="A short summary of your request"/></label><label>Your message<textarea v-model="form.text" required rows="6" maxlength="8000" placeholder="The more context, the better we can help."/></label><div class="form-row"><label>Priority<select v-model="form.priority"><option value="low">Low · a general question</option><option value="normal">Normal · I need a hand</option><option value="high">High · something is blocked</option><option value="urgent">Urgent · a service is unavailable</option></select></label><label>Request type<select v-model="form.channel"><option value="portal">Support ticket</option><option value="chat">Live conversation</option></select></label></div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button class="button secondary" type="button" @click="modal=false">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Sending…':'Send request'}}<Icon name="arrow" :size="16"/></button></div></form></Modal></div></template>
